------------------------------------------------------ public
---@param activityUuid number
---@param index number
---@param activityUuid number
function UIActivityPromoterCellNew:Refresh(taskDojo, index, activityUuid)

    if isTable(taskDojo) == false then
        printError("查出异常 task dojo " .. tostring(index))
        return
    end

    self.activityUuid = activityUuid
    self.taskDojo = taskDojo
    self.index = index

    local isHave = 0
    if checkNumber(taskDojo.only) == 1 then
        local reward = table.takeFirst(taskDojo.reward)
        local no = GoodsUtils.GetThingNo(reward.goodsId)
        if no >= 1 then
            isHave = 1
        end
    end

    CfUtils.SetActive(self.FontStyleWithGoodIconButton, checkNumber(taskDojo.currentStock) > 0 and isHave == 0)
    CfUtils.SetActive(self.txtHave, isHave == 1)
    if isHave == 0 then
        ---仍有库存
        CfUtils.SetActive(self.Black, checkNumber(taskDojo.currentStock) == 0)
        CfUtils.SetActive(self.TxtFinish, checkNumber(taskDojo.currentStock) == 0)
        CfUtils.FillText(self.TxtFinish, localize('已售罄'))
    else
        CfUtils.SetActive(self.Black, false)
        CfUtils.SetActive(self.TxtFinish, false)
    end
    local reward = table.takeFirst(taskDojo.reward)
    if isTable(reward) then
        local goodsId = checkNumber(reward.goodsId)
        local num = checkNumber(reward.num)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.FillText(self.TextDescribe, string.format("%s X%d", tostring(vo.name), num))
        CfUtils.FillText(self.TxtFrequency, localize('剩余兑换次数: _num_', { _num_ = taskDojo.currentStock }))
    end


    -- 绘制 奖励道具图标
    ---@type CommonGoodsListLight
    local commonGoodsListLight = CfUtils.GetLuaScr(self.CommonGoodsListLight, 'Game.Behaviours.CommonGoodsListLight')
    commonGoodsListLight:FreshBaseUI(taskDojo.reward)

    --按钮上的道具显示
    local consume = table.takeFirst(taskDojo.consume)
    local goodsId = checkNumber(consume.goodsId)
    local num = checkNumber(consume.num)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    local havNo = GoodsUtils.GetThingNo(goodsId)
    if checkNumber(taskDojo.currentStock) > 0 then
        CfUtils.SetActive(self.AnimRoot.transform:Find("UIFX_SpecialGlow"), checkNumber(taskDojo.specialEffects) == 1)
    else
        CfUtils.SetActive(self.AnimRoot.transform:Find("UIFX_SpecialGlow"), false)
    end
    if vo then
        CfUtils.FillImage(self.FontStyleWithGoodIconButton.transform:Find("Layout/ImgIcon"), vo.photoPath)
        if havNo >= num then
            ---充足
            CfUtils.FillText(self.FontStyleWithGoodIconButton.transform:Find("Layout/TxtNumber"), string.format_color_tag(num, '#FFFFFF'))
        else
            CfUtils.FillText(self.FontStyleWithGoodIconButton.transform:Find("Layout/TxtNumber"), string.format_color_tag(num, '#ff3939'))
        end
    end
end

function UIActivityPromoterCellNew:_OnClick_FontStyleButton()
    if isNull(self.activityUuid) or isNull(self.index) then
        printError("数据未准备好, 请检查调用时序")
        return
    end
    local consume = table.takeFirst(self.taskDojo.consume)
    local goodsId = checkNumber(consume.goodsId)
    local num = checkNumber(consume.num)
    local havNo = GoodsUtils.GetThingNo(goodsId)
    if self.taskDojo and checkNumber(self.taskDojo.only) == 1 then
        local reward = table.takeFirst(self.taskDojo.reward)
        local no = GoodsUtils.GetThingNo(reward.goodsId)
        if no >= 1 then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(reward.goodsId)
            ---已拥有后不能再买
            GameUtils.Toast(localize('当前已拥有_name_不能再进行兑换', { _name_ = goodsVo.name }))
            return
        end
    end
    if havNo < num then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        GameUtils.Toast(localize('_name_不足不能兑换', { _name_ = vo.name }))
        return
    end

    GameUtils.Request("Activity2/spreadExchange", { activityUuid = self.activityUuid, id = checkNumber(self.taskDojo.id) }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            --printError("data = " .. table.dump(response.data) )

            Events.Broadcast(Constants.EventNames.PromoterRefresh)

            -- 领取宝箱数据, 
            GoodsUtils.DrawRewards(response.data.rewards)

            -- 播放窗口动画:
            UIModule.OpenDialog({
                id = Constants.UITypeIds.UICommonRewardPop,
                parameters = { rewards = response.data.rewards }
            })
        end
    end)
end

function UIActivityPromoterCellNew:PlayFadeInAnim(index0Based)
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Wait")
        CfUtils.PlayDelayShowAnimate(self.AnimRoot, 1, ((index0Based or 1) - 1) * 0.06)
        --print("PlayFadeInAnim")
    end
end

function UIActivityPromoterCellNew:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        --print("PlayInitAnim")
        CfUtils.PlayAnimator(self.AnimRoot, "Default")
    end
end

return UIActivityPromoterCellNew
 
 